package com.govweb.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException {var header=req.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer "))try{var claims=jwt.parse(header.substring(7));var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+claims.get("role"))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){} chain.doFilter(req,res);}}
